-- Explicações por artigo — Lei do Registro de Identidade Civil (Lei nº 9.454, de 1997). Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É instituído o número único de Registro de Identidade Civil, pelo qual cada cidadão brasileiro, nato ou naturalizado, será identificado em suas relações com a sociedade e com os organismos governamentais e privados. Nos documentos novos será adotado, como número único, o número de inscrição no Cadastro de Pessoas Físicas (CPF), que é único e definitivo para cada pessoa física.', '["Número único de Registro de Identidade Civil.","Aplica-se ao brasileiro nato ou naturalizado.","O número do CPF é adotado nos documentos novos.","O CPF é único e definitivo."]'::jsonb, '["ATUALIZAÇÃO: os §§2º e 3º foram incluídos pela Lei do CPF como documento único (CPF como número único).","O §1º foi vetado."]'::jsonb, 'Os novos documentos trazem o CPF como número único do cidadão.', '["Assertiva que cria novo número para cada documento erra: o CPF é o número único."]'::jsonb, '[{"termo":"RIC","significado":"Registro de Identidade Civil."}]'::jsonb, '["Lei do CPF"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ric' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'É instituído o Cadastro Nacional de Registro de Identificação Civil, destinado a conter o número único de Registro de Identidade Civil, acompanhado dos dados de identificação de cada cidadão.', '["Cadastro Nacional de Registro de Identificação Civil.","Contém o número único e os dados de identificação."]'::jsonb, '["Base nacional unificada."]'::jsonb, 'O cadastro nacional reúne o número único e os dados de cada cidadão.', '["Assertiva que mantém cadastros estaduais isolados sem base nacional erra."]'::jsonb, '[]'::jsonb, '["Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ric' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Poder Executivo definirá a entidade que centralizará as atividades de implementação, coordenação e controle do Cadastro Nacional, que será o órgão central do Sistema Nacional de Registro de Identificação Civil. A União fica autorizada a firmar convênio com os Estados e o Distrito Federal para a implementação do número único. Os órgãos regionais coordenarão no âmbito de cada Unidade da Federação, repassando aos órgãos locais as instruções do órgão central e reportando a este as informações.', '["Executivo define o órgão central do Sistema.","Convênios da União com Estados e DF.","Órgãos regionais coordenam em cada Unidade da Federação."]'::jsonb, '["ATUALIZAÇÃO: parte do dispositivo foi revogada pela Lei nº 12.058, de 2009."]'::jsonb, 'A União firma convênio com um Estado para implantar o número único.', '["Assertiva que atribui a escolha do órgão central ao Poder Legislativo erra: é do Executivo."]'::jsonb, '[]'::jsonb, '["Art. 2º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'ric' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

